// In pom.xml, declare a dependency
<dependencies>
  <dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-web</artifactId>
    <version>3.2.0</version>
  </dependency>
</dependencies>

// Maven's resolution process:
// 1. Check local cache: ~/.m2/repository/org/springframework/boot/spring-boot-starter-web/3.2.0/
//    If found, use it immediately

// 2. If not in local cache, check Maven Central:
//    https://repo1.maven.org/maven2/org/springframework/boot/spring-boot-starter-web/3.2.0/spring-boot-starter-web-3.2.0.jar

// 3. Download JAR and POM to local cache
var localPath = "~/.m2/repository/org/springframework/boot/spring-boot-starter-web/3.2.0/spring-boot-starter-web-3.2.0.jar";

// 4. Read the POM to discover transitive dependencies
//    spring-boot-starter-web depends on spring-web, spring-webmvc, jackson-databind, etc.
//    Maven recursively downloads all transitive dependencies

// 5. All resolved JARs added to classpath for compilation

// Search Maven Central from command line
// Visit: https://search.maven.org/
// Or use Maven coordinates directly in browser:
// https://search.maven.org/artifact/org.springframework.boot/spring-boot-starter-web/3.2.0/jar
